fn add_pair(gs: List[List[Str]], a: Str, b: Str) -> List[List[Str]] {
  let empty: List[Str] = []
  let ha = gs.any(fn(g) => g.contains(a))
  let hb = gs.any(fn(g) => g.contains(b))
  let ga = gs.find(fn(g) => g.contains(a)).unwrap_or(empty)
  let gb = gs.find(fn(g) => g.contains(b)).unwrap_or(empty)
  if ha and hb {
    if ga == gb {
      return gs
    }
    let rest = gs.filter(fn(g) => (g != ga) and (g != gb))
    return rest.push(ga.concat(gb))
  }
  if ha {
    return gs.filter(fn(g) => g != ga).push(ga.push(b))
  }
  if hb {
    return gs.filter(fn(g) => g != gb).push(gb.push(a))
  }
  return gs.push([a, b].unique())
}

pub fn groups(pairs: List[List[Str]]) -> List[List[Str]] {
  let none: List[List[Str]] = []
  let merged = pairs.fold(none, fn(gs, p) => add_pair(gs: gs, a: p.get_or(0, ""), b: p.get_or(1, "")))
  let normal = merged.map(fn(g) => g.unique().sort())
  return normal.sort_by(fn(g) => g.get_or(0, ""))
}
